private const QUOTED_PERIOD_SENTINEL = "\x1A";

/**
 * Replace periods inside single-quoted worksheet names with a sentinel
 *     so that they aren't mistaken for ODS address separators.
 */
private static function protectQuotedPeriods(string $value): string
{
    $result = '';
    $quotedRegion = false;
    $length = strlen($value);
    for ($index = 0; $index < $length; ++$index) {
        $character = $value[$index];
        if ($character === "'") {
            $result .= $character;
            if ($quotedRegion && $index + 1 < $length && $value[$index + 1] === "'") {
                $result .= $value[++$index];
            } else {
                $quotedRegion = !$quotedRegion;
            }
        } elseif ($character === '.' && $quotedRegion) {
            $result .= self::QUOTED_PERIOD_SENTINEL;
        } else {
            $result .= $character;
        }
    }

    return $result;
}

private static function restoreQuotedPeriods(string $value): string
{
    return str_replace(self::QUOTED_PERIOD_SENTINEL, '.', $value);
}

public static function convertToExcelAddressValue(string $openOfficeAddress): string
{
    $protectedAddress = self::protectQuotedPeriods($openOfficeAddress);
    $excelAddress = $protectedAddress;

    // Cell range 3-d reference
    // As we don't support 3-d ranges, we're just going to take a quick and dirty approach
    //  and assume that the second worksheet reference is the same as the first
    $excelAddress = (string) preg_replace(
        [
            '/\$?([^\.]+)\.([^\.]+):\$?([^\.]+)\.([^\.]+)/miu',
            '/\$?([^\.]+)\.([^\.]+):\.([^\.]+)/miu', // Cell range reference in another sheet
            '/\$?([^\.]+)\.([^\.]+)/miu', // Cell reference in another sheet
            '/\.([^\.]+):\.([^\.]+)/miu', // Cell range reference
            '/\.([^\.]+)/miu', // Simple cell reference
        ],
        [
            '$1!$2:$4',
            '$1!$2:$3',
            '$1!$2',
            '$1:$2',
            '$1',
        ],
        $excelAddress
    );
    $excelAddress = self::restoreQuotedPeriods($excelAddress);

